import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [screen, setScreen] = useState("list");

  if (screen === "confirm") {
    return (
      <View style={styles.screen}>
        <Text nativeID="c" style={styles.h}>Захиалга баталгаажлаа</Text>
        <Pressable nativeID="home" style={styles.btn} onPress={() => setScreen("list")}>
          <Text style={styles.btnText}>Нүүр рүү</Text>
        </Pressable>
      </View>
    );
  }
  if (screen === "detail") {
    return (
      <View style={styles.screen}>
        <Text nativeID="d" style={styles.h}>Утасгүй чихэвч</Text>
        <Text>159,000₮</Text>
        <Pressable nativeID="buy" style={styles.btn}>
          <Text style={styles.btnText}>Худалдан авах</Text>
        </Pressable>
        {/* энд бичнэ үү: buy товч дархад confirm дэлгэц рүү шилж */}
      </View>
    );
  }
  return (
    <View style={styles.screen}>
      <Text style={styles.h}>Shop.mn</Text>
      <Pressable nativeID="open" style={styles.btn} onPress={() => setScreen("detail")}>
        <Text style={styles.btnText}>Утасгүй чихэвч</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 14, justifyContent: "center" },
  h: { fontSize: 22, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

